		case strings.HasPrefix(l, "+"):
			newLines = append(newLines, l[1:])
		default:
			oldLines = append(oldLines, strings.TrimPrefix(l, " "))
			newLines = append(newLines, strings.TrimPrefix(l, " "))
		}
	}
	if err := flush(); err != nil {
		return "", err
	}
